from lib import *
S = SS('n38')
steps = [
    step("Stream 的实现:拿到 c.Writer.CloseNotify() 通道,然后循环——客户端断开(clientGone 可读)就返回 true;否则调用 step(w),并立刻 w.Flush();step 返回 false 就结束(返回 false)。SSEvent 就是 c.Render(-1, sse.Event{Event: name, Data: message}),状态码 -1 表示不改状态。注意:循环里没有任何等待,节奏全靠 step 自己阻塞。", t=tl(S(1)), mark=lidx(S(1), 'clientGone := w.CloseNotify()', 'case <-clientGone:', 'w.Flush()'), done=lidx(S(1), 'keepOpen := step(w)', 'c.Render(-1, sse.Event{'), kv=KV([['每一步', 'step(w) → Flush()'], ['断开检测', 'CloseNotify() 通道'], ['节奏', '循环里没有等待,靠 step 阻塞']], ['节奏'])),
    step("c.SSEvent 写出的原始字节:响应头是 Content-Type: text/event-stream;charset=utf-8 和 Cache-Control: no-cache(没有 Connection、X-Accel-Buffering);字符串、数字 42 直接是 data:行;结构体是 JSON(<被转义成 \\u003c);多行字符串按行拆成多个 data: 行;事件名为空时不写 event: 行;[]byte 当文本;nil 会写成 data:<nil>——字面量。每个事件以空行结束。", t=tl(S(2)), mark=lidx(S(2), 'Content-Type="text/event-stream;charset=utf-8"', 'data:{"a":1,"b":"x\\u003cy"}', 'data:line2', 'data:<nil>'), done=lidx(S(2), 'event:message', 'data:没有事件名'), kv=KV([['响应头', 'text/event-stream + Cache-Control: no-cache'], ['多行', '每行一个 data:'], ['nil', '输出字面量 <nil>']], ['nil'])),
    step("真实流式(服务端每 200 ms 发一个事件,客户端逐行读并记录到达时间):c.Stream 的事件分别在 203 / 404 / 604 / 805 ms 到达,响应头 203 ms 就到了,Transfer-Encoding 是 chunked;循环里只 SSEvent、没有 Flush 时,响应头和 4 个事件全部在约 806 ms(handler 结束时)一起到达;每个事件后自己 c.Writer.Flush() 的写法和 c.Stream 一样(200 / 402 / 603 / 805 ms)。", t=tl(S(3)), mark=lidx(S(3), '/noflush'), done=lidx(S(3), '/stream', '/flush'), b=bars([['c.Stream:第 1 个事件', 203, '203 ms'], ['c.Stream:第 4 个事件', 805, '805 ms'], ['不 Flush:第 1 个事件', 806, '806 ms(与第 4 个同时)']], 806, done=[0, 1], mark=[2]), kv=KV([['c.Stream', '每步 Flush,事件即时到达'], ['不 Flush', '小响应缓冲到 handler 结束才一起发出'], ['手工 Flush', '效果与 c.Stream 相同']], ['不 Flush'])),
    step("客户端断开:连接在约 330 ms 时关闭,此时 step 已调用 6 次;断开后 31 ms,Stream 返回 clientGone=true,step 共被调用 7 次——断开之后又多调用了 1 次(CloseNotify 在下一轮循环才被检查)。", t=tl(S(4)), mark=lidx(S(4), 'clientGone=true', '多调用 1 次'), done=lidx(S(4), '客户端在约 330 ms 时断开'), kv=KV([['发现断开', 'CloseNotify,下一轮循环才检查'], ['断开后', 'step 还会多跑 1 次'], ['返回值', 'Stream 返回 true 表示客户端已断开']], ['发现断开'])),
    step("step 里不阻塞的后果:/spin 的 step 每次立即返回 true,100 ms 内被空转调用 1911526 次(一个核心打满,还不停 Flush);/wait 的 step 等 channel(3 个事件间隔 30 ms),只被调用 3 次。写 SSE 一定要让 step 阻塞在 channel、ticker 或 Request.Context().Done() 上。", t=tl(S(5)), mark=lidx(S(5), '/spin'), done=lidx(S(5), '/wait'), b=bars([['/spin:100 ms 内调用 step', 1911526, '1911526 次'], ['/wait:等 channel', 3, '3 次']], 1911526, mark=[0], done=[1]), kv=KV([['不阻塞', '空转,CPU 打满'], ['阻塞在 channel / ticker', '每个事件才调用一次'], ['原因', 'Stream 的循环自己不等待']], ['不阻塞'])),
]
A = mkartn('n38', 38, 'Gin,SSE,c.Stream,流式响应,Flush,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测流式响应:c.Stream 每步都 Flush,事件按 200 ms 间隔即时到达;循环里只 SSEvent 不 Flush 时 4 个事件在 806 ms 一起到达;SSEvent 的原始格式与响应头(nil 会写成 data:<nil>);客户端断开后 step 还会多调用 1 次;step 不阻塞会在 100 ms 内空转约 191 万次。',
    '用 Gin 做 SSE 推送,c.Stream 和 c.SSEvent 到底怎么配合?什么时候事件才会真正发给客户端?客户端断开后会怎样?这篇用真实的 HTTP 流量记下每个事件的到达时间,并验证 c.Stream 最容易踩的“step 不阻塞”问题。',
    [('203 / 404 / 604 / 805 ms', 'c.Stream 每 200 ms 发一个事件,客户端收到各事件的时间'), ('806 ms 一起到', '循环里只 SSEvent、不 Flush 时 4 个事件到达的时间'), ('191 万次 vs 3 次', 'step 不阻塞与等 channel 时,100 ms 内 step 被调用的次数')],
    [('Stream 与 SSEvent', '<p><code>SSEvent</code> 只是把事件写进 ResponseWriter,并不保证已经发给客户端。<code>Stream</code> 在每次 <code>step</code> 之后调用 <code>Flush</code>,所以事件即时到达。它的循环本身不等待:节奏完全由 <code>step</code> 决定。</p>'),
     ('事件的格式', '<p>响应头 <code>Content-Type: text/event-stream;charset=utf-8</code> 与 <code>Cache-Control: no-cache</code> 由 <code>SSEvent</code> 设置;反向代理常用的 <code>X-Accel-Buffering: no</code> 与 <code>Connection</code> 需要自己加。多行文本会拆成多个 <code>data:</code> 行,结构体序列化成 JSON,传 <code>nil</code> 会输出字面量 <code>&lt;nil&gt;</code>,别把它当作“空数据”。</p>'),
     ('Flush 的重要性', '<p>小于缓冲区(约 4 KB)的响应,不 Flush 就要等 handler 结束才发出——实测 4 个事件在 806 ms 一起到达。自己写循环时,每个事件之后都要 <code>c.Writer.Flush()</code>(与 <code>c.Stream</code> 的效果相同)。经过带缓冲的代理(nginx 默认)还需要关闭代理缓冲,本文没有验证。</p>'),
     ('客户端断开', '<p><code>Stream</code> 用 <code>CloseNotify</code>(已被标准库标记为废弃,但仍然可用)发现断开,检查发生在下一轮循环,所以断开之后 <code>step</code> 还会多执行一次。自己写循环时应该改用 <code>c.Request.Context().Done()</code> 判断。</p>'),
     ('step 必须阻塞', '<p><code>Stream</code> 不会替你等待:<code>step</code> 如果立即返回 <code>true</code>,就会变成一个空转的死循环,100 ms 内调用了近 200 万次。把 <code>step</code> 写成“从 channel 取一个事件、写出、返回 true”(或者等 ticker),这样既有节奏也不占 CPU。</p>')],
    steps,
    [ENV_N_GIN + '。用真实的 httptest.NewServer;客户端用 http.Get 与 bufio 逐行读取并记录相对 GET 开始的毫秒数;断开实验用原始 TCP 连接手写请求后 Close;每种情形各一次(数字每次运行有几毫秒抖动,空转次数每次不同)',
     '没有验证:经过 nginx 等反向代理时的缓冲;HTTP/2 下的 SSE;Last-Event-ID 的重连处理(Gin 不处理,需要自己写);大量并发 SSE 连接的资源占用;改用 Request.Context().Done() 判断断开的实际效果'],
    '流式响应与 SSE')
